CREATE TABLE goal_periods(organization_id uuid NOT NULL REFERENCES organizations(id),id uuid NOT NULL,title text NOT NULL,starts_on date NOT NULL,ends_on date NOT NULL,version int NOT NULL DEFAULT 1,archived boolean NOT NULL DEFAULT false,PRIMARY KEY(organization_id,id),CHECK(ends_on>=starts_on));
CREATE TABLE goals(organization_id uuid NOT NULL REFERENCES organizations(id),id uuid NOT NULL,title text NOT NULL,description text NOT NULL DEFAULT '',owner_type text NOT NULL CHECK(owner_type IN ('MEMBER','ROLE','CIRCLE')),owner_id uuid NOT NULL,owner_via_role_id uuid,parent_id uuid,privacy text NOT NULL DEFAULT 'PUBLIC' CHECK(privacy IN ('PUBLIC','PRIVATE')),category text NOT NULL DEFAULT 'TEAM',health text NOT NULL DEFAULT 'ON_TRACK' CHECK(health IN ('ON_TRACK','AT_RISK','BLOCKED')),lifecycle text NOT NULL DEFAULT 'ACTIVE' CHECK(lifecycle IN ('ACTIVE','CLOSED','ARCHIVED')),source text NOT NULL DEFAULT 'MANUAL' CHECK(source IN ('MANUAL','KEY_RESULTS','CHILD_GOALS','BOTH')),manual_progress numeric NOT NULL DEFAULT 0,kr_weight numeric NOT NULL DEFAULT 100,child_weight numeric NOT NULL DEFAULT 0,weight numeric NOT NULL DEFAULT 1,excluded boolean NOT NULL DEFAULT false,version int NOT NULL DEFAULT 1,created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(organization_id,id),FOREIGN KEY(organization_id,parent_id) REFERENCES goals(organization_id,id),FOREIGN KEY(organization_id,owner_via_role_id) REFERENCES entities(organization_id,id),CHECK(weight>=0 AND kr_weight>=0 AND child_weight>=0),CHECK(source<>'BOTH' OR kr_weight+child_weight=100),CHECK(owner_type='MEMBER' OR owner_via_role_id IS NULL));
CREATE TABLE goal_period_links(organization_id uuid NOT NULL,goal_id uuid NOT NULL,period_id uuid NOT NULL,PRIMARY KEY(organization_id,goal_id,period_id),FOREIGN KEY(organization_id,goal_id) REFERENCES goals(organization_id,id),FOREIGN KEY(organization_id,period_id) REFERENCES goal_periods(organization_id,id));
CREATE TABLE goal_key_results(organization_id uuid NOT NULL,id uuid NOT NULL,goal_id uuid NOT NULL,title text NOT NULL,description text NOT NULL DEFAULT '',result_type text NOT NULL CHECK(result_type IN ('QUANTITATIVE','PERCENTAGE','MILESTONE')),initial_value numeric NOT NULL DEFAULT 0,current_value numeric NOT NULL DEFAULT 0,target_value numeric NOT NULL DEFAULT 100,unit text NOT NULL DEFAULT '',weight numeric NOT NULL DEFAULT 1,excluded boolean NOT NULL DEFAULT false,archived boolean NOT NULL DEFAULT false,health text NOT NULL DEFAULT 'ON_TRACK' CHECK(health IN ('ON_TRACK','AT_RISK','BLOCKED')),version int NOT NULL DEFAULT 1,PRIMARY KEY(organization_id,id),FOREIGN KEY(organization_id,goal_id) REFERENCES goals(organization_id,id),CHECK(initial_value>=0 AND current_value>=0 AND target_value>0 AND target_value<>initial_value AND weight>=0));
CREATE TABLE goal_assignments(organization_id uuid NOT NULL,id uuid NOT NULL,goal_id uuid NOT NULL,key_result_id uuid,member_id uuid NOT NULL,functional_role text NOT NULL CHECK(functional_role IN ('LEAD','CONTRIBUTOR','FOLLOWER')),via_role_id uuid,PRIMARY KEY(organization_id,id),FOREIGN KEY(organization_id,goal_id) REFERENCES goals(organization_id,id),FOREIGN KEY(organization_id,key_result_id) REFERENCES goal_key_results(organization_id,id),FOREIGN KEY(organization_id,member_id) REFERENCES members(organization_id,id),FOREIGN KEY(organization_id,via_role_id) REFERENCES entities(organization_id,id),UNIQUE NULLS NOT DISTINCT(organization_id,goal_id,key_result_id,member_id,functional_role));
CREATE TABLE goal_history(organization_id uuid NOT NULL,id uuid NOT NULL,goal_id uuid NOT NULL,actor_id uuid NOT NULL,action text NOT NULL,snapshot jsonb NOT NULL,at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(organization_id,id),FOREIGN KEY(organization_id,goal_id) REFERENCES goals(organization_id,id));
ALTER TABLE goal_periods ENABLE ROW LEVEL SECURITY; ALTER TABLE goal_periods FORCE ROW LEVEL SECURITY; CREATE POLICY tenant ON goal_periods USING(organization_id=nullif(current_setting('orgmap.organization_id',true),'')::uuid) WITH CHECK(organization_id=nullif(current_setting('orgmap.organization_id',true),'')::uuid); GRANT SELECT,INSERT,UPDATE,DELETE ON goal_periods TO orgmap_app;
ALTER TABLE goals ENABLE ROW LEVEL SECURITY; ALTER TABLE goals FORCE ROW LEVEL SECURITY; CREATE POLICY tenant ON goals USING(organization_id=nullif(current_setting('orgmap.organization_id',true),'')::uuid) WITH CHECK(organization_id=nullif(current_setting('orgmap.organization_id',true),'')::uuid); GRANT SELECT,INSERT,UPDATE,DELETE ON goals TO orgmap_app;
ALTER TABLE goal_period_links ENABLE ROW LEVEL SECURITY; ALTER TABLE goal_period_links FORCE ROW LEVEL SECURITY; CREATE POLICY tenant ON goal_period_links USING(organization_id=nullif(current_setting('orgmap.organization_id',true),'')::uuid) WITH CHECK(organization_id=nullif(current_setting('orgmap.organization_id',true),'')::uuid); GRANT SELECT,INSERT,UPDATE,DELETE ON goal_period_links TO orgmap_app;
ALTER TABLE goal_key_results ENABLE ROW LEVEL SECURITY; ALTER TABLE goal_key_results FORCE ROW LEVEL SECURITY; CREATE POLICY tenant ON goal_key_results USING(organization_id=nullif(current_setting('orgmap.organization_id',true),'')::uuid) WITH CHECK(organization_id=nullif(current_setting('orgmap.organization_id',true),'')::uuid); GRANT SELECT,INSERT,UPDATE,DELETE ON goal_key_results TO orgmap_app;
ALTER TABLE goal_assignments ENABLE ROW LEVEL SECURITY; ALTER TABLE goal_assignments FORCE ROW LEVEL SECURITY; CREATE POLICY tenant ON goal_assignments USING(organization_id=nullif(current_setting('orgmap.organization_id',true),'')::uuid) WITH CHECK(organization_id=nullif(current_setting('orgmap.organization_id',true),'')::uuid); GRANT SELECT,INSERT,UPDATE,DELETE ON goal_assignments TO orgmap_app;
ALTER TABLE goal_history ENABLE ROW LEVEL SECURITY; ALTER TABLE goal_history FORCE ROW LEVEL SECURITY; CREATE POLICY tenant ON goal_history USING(organization_id=nullif(current_setting('orgmap.organization_id',true),'')::uuid) WITH CHECK(organization_id=nullif(current_setting('orgmap.organization_id',true),'')::uuid); GRANT SELECT,INSERT,UPDATE,DELETE ON goal_history TO orgmap_app;
